from PIL import Image, ImageOps
im = Image.open('radiograph.jpg')
zones = {
 'ul_wide': (1400, 350, 2050, 700),
 'ur_wide': (600, 350, 1250, 700),
}
for name,(x1,y1,x2,y2) in zones.items():
    c = im.crop((x1,y1,x2,y2)).resize(((x2-x1)*2,(y2-y1)*2), Image.LANCZOS)
    c = ImageOps.autocontrast(c, cutoff=1)
    c.save(f'e_{name}.png')
print('ok')
"", "description": "Create wider contrast-enhanced views of both upper molar quadrants"}

